window.products.push({"id":498547,"name":"Ninja B32002 Foodi NeverStick Premium 2-Piece Baking Sheet Set, Nonstick, Oven Safe up to 500⁰F, with 9 x 13 inch Sheet & 11 x 17 inch Sheet, Dishwash","category":"homeandappliances","retail price":39.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71nOUzPTzsL._AC_SL1500_.jpg","description":"Introducing the Ninja Foodi NeverStick 2-Piece Baking Sheet Set, the premium bakeware that easily releases food and wipes clean. Heavy gauge 0.8mm aluminized steel minimizes rusting, resists warping, and is oven safe up to 500⁰F. The NeverStick coating easily wipes clean, is dishwasher safe, and delivers perfect results every time.","images":["https://m.media-amazon.com/images/I/71nOUzPTzsL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Ninja","source_asin":"B0B3PXKKRX","category_path":"Home & Kitchen"},"sku":"BM-498547","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0B3PXKKRX","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0B3PXKKRX","price_pending":true,"merchant_ready":false});
